To search for specific elements in a vector, you can use thefind()function.

It takes three parameters:start_iterator,end_iterator,value, wherevalueis the value to search for:

To search for the first element that isgreater thana specific value, you can use theupper_bound()function:

To find the smallest element in a vector, use themin_element()function:

To find the largest element, use themax_element()function:

To copy elements from one vector to another, you can use thecopy()function:

To fill all elements in a vector with a value, you can use thefill()function:

For a complete reference of algorithm functions, go to ourC++ Algorithm Reference.

### Code Snippets

```
// Include the algorithm library
#include <algorithm>

---

// Create a vector called cars that will store strings
vector<string> cars = {"Volvo", "BMW", 
  "Ford", "Mazda"};
// Sort cars alphabetically
sort(cars.begin(), cars.end());

---

// Create a vector called numbers that will store integers
vector<int> numbers = {1, 7, 3, 5, 9, 2};
// Sort numbers numerically
sort(numbers.begin(), numbers.end());

---

// Create a vector called numbers that will store integers
vector<int> numbers = {1, 7, 3, 5, 9, 2};
// Sort numbers 
  numerically in reverse order
sort(numbers
.rbegin()
, numbers
.rend()
);

---

// Create a vector called numbers that will store integers
vector<int> 
  numbers = {1, 7, 3, 5, 9, 2};
// Sort numbers numerically, starting 
  from the fourth element (only sort 5, 9, and 2)
sort(numbers.
begin() 
  + 3
, numbers.end());

---

// Create a vector called numbers that will store integers
vector<int> 
  numbers = {1, 7, 3, 5, 9, 2};
// Search for the number 3
auto it = find(numbers.begin(), numbers.end(), 3);

---

// Create a vector called numbers that will store integers
vector<int> 
  numbers = {1, 7, 3, 5, 9, 2};
// Sort the vector in ascending order
sort(numbers.begin(), numbers.end());
// Find the first value that is greater 
  than 5 in the sorted vector
auto it = upper_bound(numbers.begin(), 
  numbers.end(), 5);

---

// Create a vector called numbers that will store integers
vector<int> 
  numbers = {1, 7, 3, 5, 9, 2};
// Find the smallest number
auto it = 
  min_element(numbers.begin(), numbers.end());

---

// Create a vector called numbers that will store integers
vector<int> 
  numbers = {1, 7, 3, 5, 9, 2};
// Find the largest number
auto it = 
  max_element(numbers.begin(), numbers.end());

---

// Create a vector called numbers that will store integers
vector<int> 
  numbers = {1, 7, 3, 5, 9, 2};
// Create a vector called copiedNumbers 
  that should store 6 integers
vector<int> copiedNumbers(6);
// 
  Copy elements from numbers to copiedNumbers
copy(numbers.begin(), 
  numbers.end(), copiedNumbers.begin());

---

// Create a vector called numbers that will store 6 integers
vector<int> 
  numbers(6);
// Fill all elements in the numbers vector with the value 
  35
fill(numbers.begin(), numbers.end(), 35);
```
